Definition sfmt_rowend (sp gp tp t2 s0 a1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s10 s11 t4 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (xp yp xn yn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t1' a0' a5' s1' s9' t5' : word),
    ms' = MS (mkR ra' sp gp tp (Z_to_bv 64 xn) t1' t2 s0 s1' a0' a1 a2 a3 a4 a5' (Z_to_bv 64 xp) (Z_to_bv 64 SHB) s2 s3 s4 s5 s6 s7 (Z_to_bv 64 1) s9' s10 s11
                  (Z_to_bv 64 yn) t4 t5' (Z_to_bv 64 yp))
             F (Z_to_bv 64 0x15bda0) fc None m (seg_rom asegs).

(* [comment removed for export] *)
Ltac sf_forks STEP :=
  lwalk [0x15c3e8];
  lazymatch goal with
  | |- evt _ _ (MS _ _ (Z_to_bv 64 0x15c3e8) _ _ _ _) => apply STEP; repeat (apply (f_equal2 pair)); lia
  | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) =>
      let H := fresh "CMP" in brfork H; rewrite ?signed_lit64 in H by lia; [sf_forks STEP | sf_forks STEP]
  end.

Lemma sfmt_elems : forall (k : nat) (j : Z)
    (ra sp gp tp t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s9 s10 s11 t4 t5 : word) F fc (m : mem)
    (rp sx cx cy i : Z) (row rest : list Z) (xp yp xn yn xp' yp' xn' yn' : Z),
  Z.of_nat k = sx - j -> 0 <= j -> (1 <= k)%nat -> 1 <= sx <= 30 -> 0 <= cx < sx -> 0 <= cy <= 30 -> 0 <= i <= 30 ->
  ra = Z_to_bv 64 (sx - j) -> s1 = Z_to_bv 64 (cx - j) -> a0 = Z_to_bv 64 (rp + 4 * j) -> s9 = Z_to_bv 64 (rp + 4 * j) ->
  t5 = Z_to_bv 64 (j - cx) -> s10 = Z_to_bv 64 (cy - i) -> s11 = Z_to_bv 64 (i - cy) ->
  rest = skipn (Z.to_nat j) row -> Z.of_nat (length row) = sx -> small3 row ->
  sfmt_row cx cy i j rest (xp, yp, xn, yn) = (xp', yp', xn', yn') -> bnd4 (xp, yp, xn, yn) ->
  0 < rp -> rp mod 8 = 0 -> rp + 4 * sx <= 2^47 ->
  u32arr asegs m rp (map (Z_to_bv 64) row) -> acc asegs m rp (4 * sx) -> mem_inv asegs m ->
  evt asegs (sfmt_rowend sp gp tp t2 s0 a1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s10 s11 t4 F fc m xp' yp' xn' yn')
    (MS (mkR ra sp gp tp (Z_to_bv 64 xn) t1 t2 s0 s1 a0 a1 a2 a3 a4 a5
             (Z_to_bv 64 xp) (Z_to_bv 64 SHB) s2 s3 s4 s5 s6 s7 (Z_to_bv 64 1) s9 s10 s11
             (Z_to_bv 64 yn) t4 t5 (Z_to_bv 64 yp))
        F (Z_to_bv 64 0x15be08) fc None m (seg_rom asegs)).
