Definition sfmt_exit (sp gp tp a1 a2 a3 a4 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (xp yp xn yn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t1' t2' s0' s1' a0' a5' a7' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' t4' t5' : word),
    ms' = MS (mkR ra' sp gp tp (Z_to_bv 64 xn) t1' t2' s0' s1' a0' a1 a2 a3 a4 a5' (Z_to_bv 64 xp) a7' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11'
                  (Z_to_bv 64 yn) t4' t5' (Z_to_bv 64 yp))
             F (Z_to_bv 64 0x15bf28) fc None m (seg_rom asegs).

(* [comment removed for export] *)
Definition sfmt_rowsP (m : mem) (sx : Z) (rowp : list Z) (rows : list (list Z)) : Prop :=
  Forall2 (fun rp row => 0 < rp /\ rp mod 8 = 0 /\ rp + 4 * sx <= 2^47 /\ u32arr asegs m rp (map (Z_to_bv 64) row)
                         /\ acc asegs m rp (4 * sx) /\ Z.of_nat (length row) = sx) rowp rows.

Lemma sfmt_rows_ok : forall (k : nat) (i : Z)
    (ra sp gp tp t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 : word) F fc (m : mem)
    (sel data sx sy cx cy : Z) (rowp : list Z) (rows rest : list (list Z)) (xp yp xn yn xp' yp' xn' yn' : Z),
  Z.of_nat k = sy - i -> 0 <= i -> (1 <= k)%nat -> 1 <= sx <= 30 -> 1 <= sy <= 30 -> 0 <= cx < sx -> 0 <= cy < sy ->
  t2 = Z_to_bv 64 (sel + 16) -> s0 = Z_to_bv 64 sx -> a7 = Z_to_bv 64 SHB -> s2 = Z_to_bv 64 cx -> s3 = Z_to_bv 64 i -> s4 = Z_to_bv 64 sx ->
  s5 = Z_to_bv 64 cy -> s6 = Z_to_bv 64 (- cx) -> s7 = Z_to_bv 64 ((sel + 16) / 8 + SHB) -> s8 = Z_to_bv 64 1 -> t4 = Z_to_bv 64 sy ->
  rest = skipn (Z.to_nat i) rows -> Z.of_nat (length rows) = sy -> Z.of_nat (length rowp) = sy -> Forall small3 rows ->
  sfmt_rows cx cy i rest (xp, yp, xn, yn) = (xp', yp', xn', yn') -> bnd4 (xp, yp, xn, yn) ->
  0 < sel -> sel mod 8 = 0 -> sel + 32 <= 2^47 -> acc asegs m sel 32 -> rw_cells asegs m (sel + 16) [C8 (Z_to_bv 64 data)] ->
  0 < data -> data mod 8 = 0 -> data + 8 * sy <= 2^47 -> acc asegs m data (8 * sy) -> u64arr asegs m data (map (Z_to_bv 64) rowp) ->
  sfmt_rowsP m sx rowp rows -> mem_inv asegs m ->
  evt asegs (sfmt_exit sp gp tp a1 a2 a3 a4 F fc m xp' yp' xn' yn')
    (MS (mkR ra sp gp tp (Z_to_bv 64 xn) t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 (Z_to_bv 64 xp) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
             (Z_to_bv 64 yn) t4 t5 (Z_to_bv 64 yp))
        F (Z_to_bv 64 0x15bda8) fc None m (seg_rom asegs)).
